package org.sample;

import org.openjdk.jcstress.annotations.*;
import org.openjdk.jcstress.infra.results.J_Result;

import static org.openjdk.jcstress.annotations.Expect.*;

@JCStressTest
@Outcome(id = "-1",   expect = ACCEPTABLE, desc = "The slot was still empty")
@Outcome(id = "8400", expect = ACCEPTABLE, desc = "Saw the whole settlement")
@Outcome(id = "0",    expect = FORBIDDEN,  desc = "Saw the settlement but not its amount")
@State
public class SlotHandoffTest {
    final SettlementSlot slot = new SettlementSlot();

    @Actor
    public void producer() {
        Settlement s = new Settlement();
        s.amountCents = 8400;                 // a plain write...
        slot.offer(s);                        // ...then the release
    }

    @Actor
    public void consumer(J_Result r) {
        Settlement s = slot.poll();           // the acquire
        r.r1 = (s == null) ? -1 : s.amountCents;
    }
}

