final class LatestBatch {
    private final AtomicReference<Batch> latest = new AtomicReference<>();

    // writer: build the batch with plain writes, then release it
    void publish(Batch b) { latest.setRelease(b); }

    // readers: an acquire read sees the batch's fields as the writer left them
    Batch current() { return latest.getAcquire(); }

    // several writers racing to set the first batch: compareAndSet, volatile semantics
    boolean publishFirst(Batch b) { return latest.compareAndSet(null, b); }
}

