class LatestBatch {
    private val latest = AtomicReference<Batch?>(null)

    // writer: build the batch with plain writes, then release it
    fun publish(b: Batch) = latest.setRelease(b)

    // readers: an acquire read sees the batch's fields as the writer left them
    fun current(): Batch? = latest.getAcquire()

    // several writers racing to set the first batch: compareAndSet, volatile semantics
    fun publishFirst(b: Batch): Boolean = latest.compareAndSet(null, b)
}

