final class ReportBox {
    private static final VarHandle READY;
    static {
        try {
            READY = MethodHandles.lookup().findVarHandle(ReportBox.class, "ready", boolean.class);
        } catch (ReflectiveOperationException e) {
            throw new ExceptionInInitializerError(e);
        }
    }

    private long total;          // plain: carried by the release below
    private int count;
    private boolean ready;       // plain field, reached only through READY

    void publish(long total, int count) {      // one writer, once
        this.total = total;                     // 1. plain writes of the data
        this.count = count;
        READY.setRelease(this, true);           // 2. release: the data can't move after this
    }

    String tryRead() {
        if (!(boolean) READY.getAcquire(this)) return null;   // 3. acquire
        return count + " payments, " + total + " cents";       // 4. sees the data
    }
}

