class ReportBox {
    private var total = 0L       // plain: carried by the release below
    private var count = 0
    private var ready = false    // plain field, reached only through READY

    fun publish(total: Long, count: Int) {      // one writer, once
        this.total = total                      // 1. plain writes of the data
        this.count = count
        READY.setRelease(this, true)            // 2. release: the data can't move after this
    }

    fun tryRead(): String? {
        if (!(READY.getAcquire(this) as Boolean)) return null   // 3. acquire
        return "$count payments, $total cents"                   // 4. sees the data
    }

    companion object {
        private val READY: VarHandle = MethodHandles.lookup()
            .findVarHandle(ReportBox::class.java, "ready", Boolean::class.javaPrimitiveType)
    }
}
